package art

import (
	"bytes"
	"context"
	"errors"
	"image/jpeg"
	"net/http"
	"os"
	"path/filepath"
	"testing"
)

// TestServiceIngest covers the per-entity flow: the crop-once 2:3 geometry
// (table-driven over frame shapes, never upscaling), the original stored
// verbatim, the override pinned on the art_<sha> token, the empty-kind
// default, and the replace-old-pair deletion.
func TestServiceIngest(t *testing.T) {
	ctx := context.Background()

	cases := []struct {
		name  string
		w, h  int
		wantW int
		wantH int
	}{
		{"landscape_trims_sides", 400, 300, 200, 300},
		{"wider_than_2x3_trims_sides", 300, 400, 266, 400},
		{"taller_than_2x3_trims_top_bottom", 200, 400, 200, 300},
		{"square_trims_sides", 200, 200, 133, 200},
		{"already_2x3_left_whole", 200, 300, 200, 300},
		{"tiny_never_upscaled", 20, 20, 13, 20},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			svc, st, root := newTestService(t)
			body := jpegBytes(t, tc.w, tc.h)
			srv, _ := newUpstream(t, serveBytes(http.StatusOK, body, 0))

			token, err := svc.Ingest(ctx, "itm_1", "item", srv.URL, "")
			if err != nil {
				t.Fatalf("Ingest: %v", err)
			}
			if want := "art_" + sha256Hex(body); token != want {
				t.Fatalf("token = %s, want %s", token, want)
			}
			// The override row is pinned on the token.
			if sel, err := st.GetArtOverride(ctx, "itm_1", "item"); err != nil || sel != token {
				t.Fatalf("GetArtOverride = %q, %v; want %q", sel, err, token)
			}
			sha := sha256Hex(body)
			// The original is stored verbatim beside the crop.
			orig, err := os.ReadFile(filepath.Join(root, sha, "original.jpeg"))
			if err != nil {
				t.Fatalf("read original: %v", err)
			}
			if !bytes.Equal(orig, body) {
				t.Fatalf("original not verbatim: %d bytes vs %d upstream", len(orig), len(body))
			}
			// The crop's geometry: the centered 2:3 rectangle.
			crop, err := os.ReadFile(filepath.Join(root, sha, croppedFile))
			if err != nil {
				t.Fatalf("read cropped: %v", err)
			}
			img, err := jpeg.Decode(bytes.NewReader(crop))
			if err != nil {
				t.Fatalf("decode cropped: %v", err)
			}
			b := img.Bounds()
			if b.Dx() != tc.wantW || b.Dy() != tc.wantH {
				t.Fatalf("crop = %dx%d, want %dx%d", b.Dx(), b.Dy(), tc.wantW, tc.wantH)
			}
			// And the token resolves to the cropped JPEG.
			path, mt, err := svc.Resolve(token)
			if err != nil {
				t.Fatalf("Resolve: %v", err)
			}
			if filepath.Base(path) != croppedFile || mt != "image/jpeg" {
				t.Fatalf("Resolve = %s (%s), want cropped.jpg + image/jpeg", path, mt)
			}
		})
	}

	// empty_kind_defaults_poster: an empty kind is stored under the
	// KindPoster cache key.
	t.Run("empty_kind_defaults_poster", func(t *testing.T) {
		svc, st, _ := newTestService(t)
		body := jpegBytes(t, 100, 150)
		srv, _ := newUpstream(t, serveBytes(http.StatusOK, body, 0))
		if _, err := svc.Ingest(ctx, "itm_k", "item", srv.URL, ""); err != nil {
			t.Fatalf("Ingest: %v", err)
		}
		if _, err := st.LookupArtFetch(ctx, urlHash(srv.URL, KindPoster)); err != nil {
			t.Fatalf("fetch row not under KindPoster key: %v", err)
		}
	})

	// replace_deletes_old_pair: a second Ingest for the same entity deletes
	// the previous blob pair (original + cropped) and re-pins the override.
	t.Run("replace_deletes_old_pair", func(t *testing.T) {
		svc, st, root := newTestService(t)
		a := jpegBytes(t, 400, 300)
		b := jpegBytes(t, 200, 300) // different frame → different content address
		srvA, _ := newUpstream(t, serveBytes(http.StatusOK, a, 0))
		srvB, _ := newUpstream(t, serveBytes(http.StatusOK, b, 0))

		tokenA, err := svc.Ingest(ctx, "itm_r", "item", srvA.URL, "")
		if err != nil {
			t.Fatalf("Ingest A: %v", err)
		}
		dirA := filepath.Join(root, sha256Hex(a))
		if _, err := os.Stat(filepath.Join(dirA, croppedFile)); err != nil {
			t.Fatalf("old pair missing before replace: %v", err)
		}

		tokenB, err := svc.Ingest(ctx, "itm_r", "item", srvB.URL, "")
		if err != nil {
			t.Fatalf("Ingest B: %v", err)
		}
		if tokenB == tokenA {
			t.Fatal("token B = token A, want distinct content addresses")
		}
		if _, err := os.Stat(dirA); !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("old pair stat = %v, want os.ErrNotExist (pair deleted)", err)
		}
		if sel, err := st.GetArtOverride(ctx, "itm_r", "item"); err != nil || sel != tokenB {
			t.Fatalf("override after replace = %q, %v; want %q", sel, err, tokenB)
		}
		if _, err := os.Stat(filepath.Join(root, sha256Hex(b), croppedFile)); err != nil {
			t.Fatalf("new pair missing: %v", err)
		}
	})
}
